}
// front wall with the round door
const doorCenterC = new THREE.Vector3(C.center.x, WORLD.platform.topY + 7.0, C.zDoor);
const cf = new THREE.Shape();
cf.absarc(C.center.x, C.center.y, C.radius, 0, Math.PI * 2, false);
