  course: Course,
  s0: number,
  s1: number,
  opts: { window: number; taper: number; baseRadius: (s: number) => number },
): TubePath {
  const ds = 0.5;
  const n = Math.ceil((s1 - s0) / ds) + 1;
  const S = (i: number) => Math.min(s1, s0 + i * ds);
  const axis: THREE.Vector3[] = [];
